CREATE TABLE "supply_reservations" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "run" text NOT NULL,
  "opened_step" bigint NOT NULL,
  "last_step" bigint NOT NULL,
  "account" bigint NOT NULL,
  "source" text NOT NULL,
  "reservation" text NOT NULL,
  "amount_micros" bigint NOT NULL,
  "unit_micros" bigint NOT NULL,
  "covered_micros" bigint NOT NULL DEFAULT 0,
  "expires_at" bigint,
  "state" text NOT NULL DEFAULT 'open'
);

CREATE INDEX "supply_reservations_open" ON "supply_reservations" (account) WHERE state = 'open';
CREATE INDEX "supply_reservations_run" ON "supply_reservations" (run);

CREATE TABLE "supply_settlements" (
  "key" text PRIMARY KEY,
  "ask" text NOT NULL,
  "owed_at" bigint NOT NULL,
  "due_at" bigint NOT NULL,
  "tries" bigint NOT NULL DEFAULT 0,
  "failure" text
);
